\begin{tikzpicture}[font=\sffamily, scale=1.1]
    % Axes
    \draw[-latex] (0, -3.5) -- (0, 4) node[anchor=south] {Potential / mV};
    \draw[-latex] (0, -2.5) -- (8.5, -2.5) node[anchor=west] {Time / ms};

    % Resting potential line
    \draw[dashed, gray] (0, -1.5) -- (8, -1.5) node[right, black, font=\footnotesize] {$-70$ (Resting potential)};
    \draw[dashed, gray] (0, 2.5) -- (8, 2.5) node[right, black, font=\footnotesize] {$+40$};

    % Y-axis ticks and labels
    \node[left] at (0, 2.5) {$+40$};
    \node[left] at (0, -1.5) {$-70$};
    \node[left] at (0, -2.5) {$0$};

    % Action potential curve
    \draw[thick] (0.5, -1.5) -- 
        (2, -1.5) node[circle,fill,inner sep=1pt,label=above left:A] {} .. controls (2.5, -1.5) and (2.8, 0) .. 
        (3, 2.5) node[circle,fill,inner sep=1pt,label=above:B] {} .. controls (3.3, 3) and (3.8, -2) .. 
        (4.5, -2.5) node[circle,fill,inner sep=1pt,label=below:C] {} .. controls (4.8, -3) and (5.2, -2) .. 
        (5.8, -1.5) node[circle,fill,inner sep=1pt,label=above right:D] {} -- 
        (7.5, -1.5);

    % Additional labels for stages if needed by question context (points A, B, C, D are explicitly requested)

    % Figure caption
    \node at (4.25, -4.2) {Fig. 9.1};
\end{tikzpicture}
